window.ScripturaLexicons.BDAG_PART_0286 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-01\" data-source=\"BDAG\" data-search=\"πηρός, ά, όν adjetivo mutilado; incapacitado; cego BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πηρός, ά, όν</td><td>adjetivo</td><td>mutilado; incapacitado; cego</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-02\" data-source=\"BDAG\" data-search=\"πηρόω verbo incapacitar; mutilar; cegar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πηρόω</td><td>verbo</td><td>incapacitar; mutilar; cegar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-03\" data-source=\"BDAG\" data-search=\"πήρωσις, εως, ἡ substantivo feminino incapacidade física; cegueira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πήρωσις, εως, ἡ</td><td>substantivo feminino</td><td>incapacidade física; cegueira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-04\" data-source=\"BDAG\" data-search=\"πηχυαῖος, α, ον adjetivo com um côvado de comprimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πηχυαῖος, α, ον</td><td>adjetivo</td><td>com um côvado de comprimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-05\" data-source=\"BDAG\" data-search=\"πῆχυς, εως, ὁ substantivo masculino côvado; medida de comprimento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πῆχυς, εως, ὁ</td><td>substantivo masculino</td><td>côvado; medida de comprimento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-06\" data-source=\"BDAG\" data-search=\"πιάζω verbo agarrar; prender; capturar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πιάζω</td><td>verbo</td><td>agarrar; prender; capturar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-07\" data-source=\"BDAG\" data-search=\"πίε, πιεῖν, πίεσαι remissão verbal ver πίνω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πίε, πιεῖν, πίεσαι</td><td>remissão verbal</td><td>ver πίνω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-08\" data-source=\"BDAG\" data-search=\"πιέζω verbo pressionar; comprimir; esmagar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πιέζω</td><td>verbo</td><td>pressionar; comprimir; esmagar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-09\" data-source=\"BDAG\" data-search=\"πιθανολογία, ας, ἡ substantivo feminino discurso persuasivo; argumentação especiosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πιθανολογία, ας, ἡ</td><td>substantivo feminino</td><td>discurso persuasivo; argumentação especiosa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-10\" data-source=\"BDAG\" data-search=\"πίθηκος, ου, ὁ substantivo masculino macaco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πίθηκος, ου, ὁ</td><td>substantivo masculino</td><td>macaco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-11\" data-source=\"BDAG\" data-search=\"πιθός remissão ortográfica grafia preferida de πειθός BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πιθός</td><td>remissão ortográfica</td><td>grafia preferida de πειθός</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-12\" data-source=\"BDAG\" data-search=\"πικραίνω verbo tornar amargo; amargar-se; ressentir-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πικραίνω</td><td>verbo</td><td>tornar amargo; amargar-se; ressentir-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-13\" data-source=\"BDAG\" data-search=\"πικρία, ας, ἡ substantivo feminino amargor; amargura; animosidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πικρία, ας, ἡ</td><td>substantivo feminino</td><td>amargor; amargura; animosidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-14\" data-source=\"BDAG\" data-search=\"πικρός, ά, όν adjetivo amargo; áspero; severo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πικρός, ά, όν</td><td>adjetivo</td><td>amargo; áspero; severo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-15\" data-source=\"BDAG\" data-search=\"πικρῶς advérbio amargamente; dolorosamente; ferozmente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πικρῶς</td><td>advérbio</td><td>amargamente; dolorosamente; ferozmente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-16\" data-source=\"BDAG\" data-search=\"Πιλᾶτος, ου, ὁ nome próprio masculino Pilatos; Pôncio Pilatos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πιλᾶτος, ου, ὁ</td><td>nome próprio masculino</td><td>Pilatos; Pôncio Pilatos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-17\" data-source=\"BDAG\" data-search=\"πίμπλημι verbo encher; completar; saciar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πίμπλημι</td><td>verbo</td><td>encher; completar; saciar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-18\" data-source=\"BDAG\" data-search=\"πίμπρημι verbo arder de febre; inchar; distender-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πίμπρημι</td><td>verbo</td><td>arder de febre; inchar; distender-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-19\" data-source=\"BDAG\" data-search=\"πινακίδιον, ου, τό substantivo neutro pequena tabuinha de escrever BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πινακίδιον, ου, τό</td><td>substantivo neutro</td><td>pequena tabuinha de escrever</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0286-20\" data-source=\"BDAG\" data-search=\"πινακίς, ίδος, ἡ substantivo feminino pequena tabuinha de escrever BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πινακίς, ίδος, ἡ</td><td>substantivo feminino</td><td>pequena tabuinha de escrever</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0286-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πηρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (veja as duas entradas seguintes; Hom. e outros; papiros; ApcrEzk [Epiph 70, 15]; SibOr 3, 793; Philo; Just.; Mel., P. 78, 564), relativo à deficiência em qualquer parte do corpo, mutilado, incapacitado, debilitado; com referência aos olhos, cego (Appian, Samn. 9 §5; Aesop, Fab. 37 P. = 57 H.; 37 H-H.; 54 Ch.); figuradamente (Philo, Somn. 1, 27 <span class=\"greek\">πρὸς</span> <span class=\"greek\">αἴσθησιν</span> <span class=\"greek\">πηροί</span>; Ps.-Lucian, Am. 46 <span class=\"greek\">πηροὶ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">διανοίας</span> <span class=\"greek\">λογισμοί</span>), <span class=\"greek\">πηροὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">διανοίᾳ</span> «cegos no entendimento» 2 Cl 1:6.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πηρόω</span> (<span class=\"greek\">πηρός</span>), aoristo, 3.ª pessoa do singular <span class=\"greek\">ἐπήρωσεν</span> 4 Macc 18:21; perfeito passivo <span class=\"greek\">πεπήρωνται</span> Job 17:7, variante textual (Aristoph., Hippocr. e outros; Job 17:7, variante textual; 4 Macc 18:21; Philo; Jos., C. Ap. 2, 15; Just., D. 12, 2), causar deficiência física, incapacitar, mutilar; em nossa literatura, ocorre em vários lugares como variante textual de <span class=\"greek\">πωρόω</span> (os testemunhos também variam dessa mesma maneira em Job 17:7). Na linguagem figurada, <span class=\"greek\">ἐπήρωσεν</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">καρδίαν</span> «fechou-lhes o entendimento» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:40</a>, variante textual. Passivo (M. Ant. 5, 8, 13), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:17</a> D*. <span class=\"greek\">οἱ</span> <span class=\"greek\">λοιποὶ</span> <span class=\"greek\">ἐπηρώθησαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:7</a>, variante textual (atestada insuficientemente por um único manuscrito tardio 66** [veja Tdf.] = Gregory 1911; aqui, o significado é certamente «cegar», que <span class=\"greek\">πηρόω</span> já apresenta desde Aristot., HA 620a, 1 e Ephorus [IV a.C.]: 70 Fgm. 1 Jac.; semelhantemente, escólio sobre Apollon. Rhod. 2, introdução e 2, 182). Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:3</a>, variante textual, veja <span class=\"greek\">πληρόω</span> 1a.—DELG s.v. <span class=\"greek\">πηρός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πήρωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πήρωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πηρόω</span>; desde Democr. 296; Hippocr.; Maximus Tyr. 29, 2f; Dt 28:28 Aq.; Philo; Jos., Ant. 1, 267; Ath., R. 21 p. 75, 3 e outros), estado de deficiência física, incapacidade, especialmente também deficiência visual, cegueira (Dio Chrys. 47 [64], 6; Artem. 2, 36 p. 134, 28 <span class=\"greek\">ὀφθαλμῶν</span> <span class=\"greek\">π</span>.; Lucian, Dom. 29); figuradamente (Manetho, Apot. 4, 518 <span class=\"greek\">π</span>. <span class=\"greek\">ψυχῆς</span>; Philo, Ebr. 160, Omn. Prob. Lib. 55 <span class=\"greek\">λογισμοῦ</span> <span class=\"greek\">π</span>.), <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:5</a>, variante textual (veja <span class=\"greek\">πώρωσις</span>).—DELG s.v. <span class=\"greek\">πηρός</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πηχυαῖος, α, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πηχυαῖος</span>, <span class=\"greek\">α</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">πῆχυς</span>; Hdt. e outros; inscrições), do comprimento de um côvado (cerca de 18 polegadas), acerca de varas, Hs 8, 1, 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῆχυς, εως, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πῆχυς</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ὁ</span> (Hom.+; inscrições, papiros, LXX, En, TestSol, TestAbr; TestJud 3:7; GrBar, ApcEsdr, EpArist, Philo, Joseph., apologistas); genitivo plural <span class=\"greek\">πηχῶν</span> (não ático: X., An. 4, 7, 16; Polyb., Diod S, Hero Alex., Plut.; SIG 1231, 14; papiros [Mayser p. 267]; LXX [veja Thackeray p. 151, 21]; En 7:2; Jos., Bell. 6, 166, C. Ap. 2, 119; SibOr 5, 57.—Phryn. p. 245 Lob.; Schwyzer I 573; Dssm., B 152 [BS 153s.]; B-D-F §48; Mlt-H. 140s.). Originalmente «antebraço»; depois, côvado, medida de comprimento (Poll. 2, 158: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὠλεκράνου</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μέσου</span> <span class=\"greek\">δακτύλου</span> <span class=\"greek\">ἄκρον</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">διάστημα</span> <span class=\"greek\">πῆχυς</span> = «um côvado é a distância do cotovelo à ponta do dedo médio»; cerca de 45–52 cm.—KHermann, Lehrb. der griech. Antiquitäten IV3 1882, 438ss.; FHultsch, APF 3, 1906, 438ss.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:17</a> (a cidade maravilhosa descrita por Luciano [Ver. Hist. 2, 11] não é medida pelo côvado humano comum, mas pelo <span class=\"greek\">πῆχυς</span> <span class=\"greek\">βασιλικός</span>). <span class=\"greek\">ὡς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">πηχῶν</span> <span class=\"greek\">διακοσίων</span> «a cerca de noventa metros de distância» (veja <span class=\"greek\">ἀπό</span> 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:8</a>. <span class=\"greek\">προσθεῖναι</span> <span class=\"greek\">πῆχυν</span> (cf. Epicharmus em Diog. L. 3, 11 <span class=\"greek\">μέτρον</span> <span class=\"greek\">παχυαῖον</span> <span class=\"greek\">ποτθέμειν</span>): <span class=\"greek\">προσθεῖναι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἡλικίαν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">π</span>. (<span class=\"greek\">ἔνα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:25</a> (Damasc., Vi. Isid. 166, acerca de crescimento espiritual: <span class=\"greek\">αὔξεσθαι</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πῆχυν</span>; Epict. 3, 2, 10 <span class=\"greek\">γέγονέ</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ψυχάριον</span> <span class=\"greek\">ἀντὶ</span> <span class=\"greek\">δακτυλιαίου</span> <span class=\"greek\">δίπηχυ</span> = «tua pequena alma, do comprimento de um dedo, tornou-se de dois côvados» [porque foste elogiado]). Essa expressão gerou duas importantes linhas interpretativas: em referência à duração da vida (veja <span class=\"greek\">ἡλικία</span> 1a e cf. Mimnermus 2, 3 Diehl2 <span class=\"greek\">πήχυιον</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">χρόνον</span> = «por apenas um côvado de tempo»), «acrescentar uma única hora à duração de vossa vida» NRSV; cf. Betz, SM p. 475s.; ou em referência ao crescimento corporal, «acrescentar um côvado à própria altura / estatura» NRSV, nota marginal. A primeira interpretação foi recomendada porque a adição de um côvado no sentido de tempo parece pequena, ao passo que um <span class=\"greek\">πῆχυς</span> de estatura corporal seria monstruosamente grande (Alcaeus, Fgm. 50 D.2 dá a medida de um gigante enorme como inferior a 5 côvados). Mas essa objeção não leva em conta o uso frequente da hipérbole no discurso do Senhor. Ademais, o contexto de ambas as passagens trata de alimento e vestuário. O alimento fornece sustento tanto para o crescimento como para a vida. Os discípulos não alcançam sua altura presente por meio da preocupação. A descrição <span class=\"greek\">ἐλάχιστον</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:26</a>) parece uma ironia extremamente refinada, que leva a hipérbole ao clímax.—B. 236s. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιάζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πιάζω</span>, 1.º aoristo <span class=\"greek\">ἐπίασα</span>. Passivo: futuro <span class=\"greek\">πιασθήσεται</span> Sir 23:1; aoristo <span class=\"greek\">ἐπιάσθην</span> (Alcman 28 D.2; Theocr. 4, 35; Sethianische Verfluchungstafeln 49, 58; 59 Wünsch [1898]; POxy 812, 5 [5 a.C.]; PHamb 6, 16; LXX [veja Thackeray 282.—B-D-F §29, 2; 101 p. 48; Mlt-H. 69; 254; 405]; TestNapht 5:2, 3). Forma dórica e coloquial correspondente ao ático <span class=\"greek\">πιέζω</span> (veja Thumb 67, nota); em nossa literatura, somente nos sentidos seguintes.<br>① Agarrar firmemente, segurar; em sentido neutro, pegar, segurar, <span class=\"greek\">τινά</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χειρός</span> «alguém pela mão» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:7</a> (cf. Theocr. 4, 35 <span class=\"greek\">τὸν</span> <span class=\"greek\">ταῦρον</span> <span class=\"greek\">ὁπλᾶς</span>).<br>② Apoderar-se com a intenção de subjugar ou controlar.<br>ⓐ Acerca de seres humanos, agarrar, prender, pôr sob custódia (cf. BGU 325, 2 <span class=\"greek\">λῃστοπιαστής</span>), <span class=\"greek\">τινά</span> «alguém» (PGM 5, 172 <span class=\"greek\">κλέπτην</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:30</a>, 32, 44; 8:20; 10:39; 11:57; PEg2, 26 e 28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:32</a>. <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ν</span> <span class=\"greek\">πιάσας</span> <span class=\"greek\">ἔθετο</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φυλακήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:4</a>.<br>ⓑ Acerca de animais, capturar (SSol 2:15); de peixes (PLond II, 483, 76 p. 328 [616 d.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:3</a>, 10. Passivo: <span class=\"greek\">ἐπιάσθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">θηρίον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:20</a>. Sobre <span class=\"greek\">πιάζω</span> e a forma correspondente <span class=\"greek\">πιέζω</span>, veja GShipp, Modern Greek Evidence for the Ancient Greek Vocabulary ’79, 454s.—B. 575; 744. New Docs 3, 82.—DELG s.v. <span class=\"greek\">πιέζω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίε, πιεῖν, πίεσαι</h1><div class=\"entry-meta\"><span>remissão verbal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πίε</span>, <span class=\"greek\">πιεῖν</span>, <span class=\"greek\">πίεσαι</span>: veja <span class=\"greek\">πίνω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιέζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πιέζω</span>, passivo: particípio perfeito <span class=\"greek\">πεπιεσμένος</span>; aoristo, 3.ª pessoa do singular <span class=\"greek\">ἐπιέσθη</span> Papias (variante textual) (Hom.+; Hero Alex. I p. 58, 4; SIG 904, 7; PCairZen 378, 11 [III a.C.]; PBerlZill 1, 41; Mi 6:15 <span class=\"greek\">πιέσεις</span> <span class=\"greek\">ἐλαίαν</span>; TestSol 1:2 C; Philo, Migr. Abr. 157, Aet. M. 129; Jos., Ant. 17, 28. Veja <span class=\"greek\">πιάζω</span>), pressionar: <span class=\"greek\">μέτρον</span> <span class=\"greek\">πεπιεσμένον</span> «uma medida comprimida, bem calcada» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:38</a>. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἁμάξης</span> … <span class=\"greek\">ἐπιέσθη</span> <span class=\"greek\">ὥστε</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔγκατα</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἐκκενωθήναι</span> «Judas ficou tão comprimido pela carroça que suas entranhas saíram» Papias (3:2, variante textual [Preuschen p. 98, aparato, linha 8]).—Veja Shipp, <span class=\"greek\">πιάζω</span>, final. B. 575; 744. New Docs 3, 82.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθανολογία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πιθανολογία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πιθανός</span> «persuasivo, plausível», cf. <span class=\"greek\">πείθω</span>), discurso persuasivo, arte da persuasão (assim Pla., Theaet. 162e); em sentido desfavorável na sua única ocorrência em nossa literatura: <span class=\"greek\">ἐν</span> <span class=\"greek\">πιθανολογίᾳ</span> «com argumentos especiosos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:4</a> (cf. PLips 40 III, 7 <span class=\"greek\">διὰ</span> <span class=\"greek\">πιθανολογίας</span>).—DELG s.v. <span class=\"greek\">πείθομαι</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίθηκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πίθηκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aristoph., Pla. e outros; Lucian, Philops. 5; Plut., Mor. 52b; papiros [Sb 2009; 2629]; 2 Ch 9:21; Jos., Ant. 8, 181; Ar. 12, 7; Tat. 18, 2), macaco, PtK 2 p. 14, 20. DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιθός</h1><div class=\"entry-meta\"><span>remissão ortográfica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πιθός</span>, grafia preferida pelos editores em lugar de <span class=\"greek\">πειθός</span> (veja esse verbete).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πικραίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πικραίνω</span>, futuro <span class=\"greek\">πικρανῶ</span>; aoristo <span class=\"greek\">ἐπίκρανα</span> LXX. Passivo: futuro, 3.ª pessoa do plural <span class=\"greek\">πικρανθήσονται</span> Jer 40:9; 1.º aoristo <span class=\"greek\">ἐπικράνθην</span>. Originalmente, «tornar acre», especialmente ao paladar (veja as três entradas seguintes).<br>① Fazer tornar-se amargo, tornar amargo em sentido físico (Hippocr. e outros): <span class=\"greek\">πικρανεῖ</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κοιλίαν</span> (<span class=\"greek\">κοιλία</span> 1b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:9</a>. Passivo, acerca do estômago: <span class=\"greek\">ἐπικράνθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">κοιλία</span> v. 10. Acerca de algo ingerido: (<span class=\"greek\">τὰ</span> <span class=\"greek\">ὕδατα</span>) <span class=\"greek\">ἐπικράνθησαν</span> 8:11 (provavelmente não em referência a <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνθρωποι</span>, no sentido de «tornaram-se amargos» = envenenados?). Acerca do mel quando se mistura a ele absinto, Hm 5, 1, 5.<br>② Provocar sentimentos amargos, amargurar, tornar amargo, em sentido afetivo (Pla.+; LXX; ApcrEzk Denis p. 122, 3 [Epiph. 70, 14]); passivo, em sentido intransitivo, tornar-se amargo ou ressentido, em uso absoluto (Demosth., Ep. 1, 6; Ep. 6 de Apollonius of Tyana: Philostrat. I 346, 19; Is 14:9; Philo, Mos. I, 302) Hm 10, 2, 3. <span class=\"greek\">π</span>. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> «estar ressentido contra alguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:19</a> (<span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> como em Lynceus, em Athen. 6, 242b).—DELG s.v. <span class=\"greek\">πικρός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πικρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πικρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πικρός</span>; Demosth., Aristot. e outros; papiros, LXX; TestSol 5:13; TestAbrA; TestLevi 11:7; TestNapht 2:8; ApcMos 24; Just., D. 120, 2).<br>① Estado de ser amargo ao paladar, amargor (Theophr., CP 6, 10, 7; Plut., Mor. 897a), mas empregado figuradamente, acerca de uma <span class=\"greek\">βοτάνη</span> <span class=\"greek\">πικρίαν</span> <span class=\"greek\">ἔχουσα</span>, «planta de sabor amargo» GEg 252, 54 (Diog. L. 9, 80: <span class=\"greek\">πικρός</span> significa «não comestível», em contraste com <span class=\"greek\">ἐδώδιμος</span>. Igualmente Jos., Ant. 3, 30: <span class=\"greek\">πικρία</span> = «não comestibilidade»). Uma pessoa reprovável é denominada <span class=\"greek\">χολὴ</span> <span class=\"greek\">πικρίας</span> = <span class=\"greek\">χολὴ</span> <span class=\"greek\">πικρά</span> (sobre a estreita conexão entre <span class=\"greek\">χολή</span> e <span class=\"greek\">πικρία</span>, veja Vett. Val. 249, 16; Dt 29:17; La 3:19; TestNapht 2:8), «fel amargo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:23</a>. <span class=\"greek\">ῥίζα</span> <span class=\"greek\">πικρίας</span> «raiz amarga, raiz que produz fruto amargo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:15</a> (cf. Dt 29:17; Hippocr., Ep. 16, 4 <span class=\"greek\">τ</span>. <span class=\"greek\">πικρὴν</span> <span class=\"greek\">ῥίζαν</span> <span class=\"greek\">ἐκκόψαι</span>).<br>② Estado de amargura em sentido afetivo, amargura, animosidade, ira, aspereza; extensão figurada de 1 (cf. Demosth. e outros; Bion de Borístenes [III a.C.] em Diog. L. 4, 46 [sobre a crueldade desumana de um proprietário de escravos]; LXX, Philo); associada a <span class=\"greek\">ὀξυχολία</span> Hm 5, 2, 4; 5, 2, 8; 6, 2, 5. <span class=\"greek\">ἐν</span> <span class=\"greek\">π</span>. <span class=\"greek\">γίνεσθαι</span> «tornar-se ressentido» m 5, 2, 2. <span class=\"greek\">ἐπιτάσσειν</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">π</span>. «dar uma ordem a alguém com aspereza» B 19:7; cf. D 4:10. Com <span class=\"greek\">θυμός</span>, <span class=\"greek\">ὀργή</span> e outros (cf. Philo, Ebr. 223; Jos., Ant. 17, 148) numa lista de vícios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:31</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">στόμα</span> <span class=\"greek\">ἀρᾶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πικρίας</span> <span class=\"greek\">γέμει</span> «a boca está cheia de maldições e de palavras amargas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:14</a> (Ps 13:3; cf. 9:28. <span class=\"greek\">π</span>. <span class=\"greek\">γέμειν</span> como em Philo, Migr. Abr. 36).—DELG s.v. <span class=\"greek\">πικρός</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πικρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πικρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (Hom. e outros; papiros, LXX, pseudoepígrafos, apologistas).<br>① Relativo ao sabor amargo, amargo (oposto a <span class=\"greek\">γλυκύς</span>; cf. Pla., Theaet. 166e <span class=\"greek\">πικρῷ</span> <span class=\"greek\">γλυκὺ</span> <span class=\"greek\">μεμιγμένον</span>; Pr 27:7), acerca de água que não é potável (como Appian, Iber. 88, §385; Ex 15:23; Demetr.: 722 Fgm. 4 Jac.; Philo, Rer. Div. Her. 208; Jos., Bell. 4, 476; 7, 186 [oposto a <span class=\"greek\">γλυκύς</span>]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:11</a> (<span class=\"greek\">τ</span>̣<span class=\"greek\">ό</span>[<span class=\"greek\">ν</span> <span class=\"greek\">θ</span>]<span class=\"greek\">υμ</span>̣[<span class=\"greek\">όν</span>], assim o editor de P74; mas talvez se deva ler <span class=\"greek\">τὸ</span> [<span class=\"greek\">ἀλ</span>]<span class=\"greek\">υκ</span>̣[<span class=\"greek\">όν</span>], veja o aparato crítico do N.).<br>② Relativo à amargura de sentimentos ou atitudes, amargo, ressentido, áspero, extensão figurada de 1: <span class=\"greek\">ζῆλον</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> «ter ciúme amargo no coração» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:14</a>. Acerca de <span class=\"greek\">ὀξυχολία</span> (<span class=\"greek\">πικρία</span> 2) Hm 5, 1, 6. Acerca dos mandamentos do diabo m 12, 4, 6. Acerca de pessoas (trágicos e outros; Diod S 14, 65, 4 <span class=\"greek\">π</span>. <span class=\"greek\">τύραννος</span>; Aelian, Fgm. 74 p. 222, 27; 103 p. 235, 24; Alciphron 1, 15, 5; Philo, Omn. Prob. Lib. 106; Jos., C. Ap. 2, 277; Ath. 31, 1), áspero (com <span class=\"greek\">ὀξύχολος</span> e <span class=\"greek\">ἄφρων</span>) m 6, 2, 4; (com <span class=\"greek\">ἄσπλαγχνος</span>) Hs 6, 3, 2. <span class=\"greek\">λέοντα</span> … <span class=\"greek\">π</span>. <span class=\"greek\">λίαν</span> «um leão muito feroz» AcPl Ha 4, 20. Acerca da paciência, <span class=\"greek\">μηδὲν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἑαυτῇ</span> <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">πικρόν</span> «que não contém em si nenhuma amargura» Hm 5, 2, 3.—B. 1033.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πικρῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πικρῶς</span>, advérbio de <span class=\"greek\">πικρός</span> (Aeschyl. e outros; papiros, por exemplo PPetr III p. 115, 42 H (8)f, 8 [III a.C.]; LXX, TestSol, TestAbr A; JosAs, ApcEsdr; Ar. 12, 2; Mel., P. 26, 181), amargamente; figuradamente (Diod S 3, 71, 3, sobre a opressão dolorosa do governo de Cronos; Appian, Liby. 100 §472 <span class=\"greek\">π</span>. <span class=\"greek\">κολάζειν</span> = «punir severamente»; Jos., Ant. 9, 118 <span class=\"greek\">βλασφημεῖν</span>) <span class=\"greek\">κλαίειν</span> (Is 22:4; 33:7; TestAbr A 11 p. 90, 6 [Stone p. 28]; JosAs 10:17; ApcrEsdr 5:8 p. 30, 1 Tdf.), «chorar amargamente» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.75\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:75</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.62\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:62</a>; GJs 13:1, 3; 15:3. <span class=\"greek\">ὁ</span> <span class=\"greek\">λέων</span> … <span class=\"greek\">ὠρύετο</span> <span class=\"greek\">πικρῶς</span> «o leão rugia ferozmente» AcPl 2, 7 Ha.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πιλᾶτος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πιλᾶτος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (também -<span class=\"greek\">άτος</span>; sobre a forma <span class=\"greek\">Πειλᾶτος</span>, preferida por Tdf. e W-H., veja Tdf., Proleg. 84s.; W-H., aparato 155. Sobre o emprego do artigo com esse nome, W-S. §18, 6d), Pilatos (Pôncio P.), prefeito (sobre a inscrição latina restaurada de maneiras diversas, mas aqui citada segundo o texto de Ehrenberg-Jones n.º 369: TIBERIEVM [. . PON]TIVS PILATVS [. . . . PRAEF]ECTVS IVDA[EA]E; veja Schürer I 358 nota 22; JVardaman, JBL 81, ’62, 70s.; Boffo, Iscrizioni n.º 25 [bibliografia]; veja também Mason 142s. sobre a nomenclatura) da Judeia entre 26–36 d.C. (veja PHedley, bibliografia citada sob <span class=\"greek\">Φῆλιξ</span>). Desempenhou o papel decisivo no julgamento de Jesus e ordenou sua crucificação: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:2</a>ss.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:1</a>ss.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:1</a>; 13:1 (único lugar de nossa literatura em que se apresenta um detalhe de sua vida fora da narrativa da Paixão: SJohnson, ATR 17, ’35, 91–95; JBlinzler, NovT 2, ’58, 24–49); 23:1ss.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:29</a>ss.; 19:1ss.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:13</a>; 4:27; 13:28, 29 D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:13</a> (veja <span class=\"greek\">μαρτυρέω</span> 1c); IMg 11; ITr 9:1; ISm 1:2; GPt 1:1; 2:3–5; 8:29, 31; 11:43, 45s., 49. (Cf. Just.; Mel., P. 92, 693.—Fontes não cristãs, especialmente Tacitus, Ann. 15, 44; Philo, Leg. ad Gai. 299–305, baseado numa carta de Agripa I; Jos., Bell. 2, 169–77, Ant. 18, 35; 55–64; 85–89; 177.)<br>—Schürer I 383–87, 438–40; HPeter, Pontius Pilatus: NJklA 19, 1907, 1–40; KKastner, Jesus vor Pilatus 1912; MDibelius, «Herodes u. Pilatus»: ZNW 16, 1915, 113–26; BEaston, The Trial of Jesus: AJT 19, 1915, 430–52; RHusband, The Prosecution of Jesus 1916; FDoerr (advogado), Der Prozess Jesu in rechtsgesch. Beleuchtung 1920; GBertram, Die Leidensgesch. Jesu u. der Christuskult 1922, 62–72; GLippert (advogado), Pil. als Richter 1923; PRoué, Le procès de Jésus 1924; GRosadi, D. Prozess Jesu 1926, Il processo di Gesù14 ’33; GAicher, D. Proz. Jesu 1929; MRadin, The Trial of Jes. of Naz. ’31; SLiberty, The Importance of P. P. in Creed and Gosp.: JTS 45, ’44, 38–56; JBlinzler, D. Prozess Jesu4 ’69, Münchener Theol. Ztschr. 5, ’54, 171–84.<br>—Sobre a esposa de Pilatos: EFascher, TLZ 72, ’47, 201–4; AOepke, ibid. 73, ’48, 743–46.<br>—Veja ainda o verbete <span class=\"greek\">ἀποκτείνω</span> 1a e Feigel, Weidel e Finegan sob <span class=\"greek\">Ἰούδας</span> 6.—EStauffer, Zur Münzprägung u. Judenpolitik des Pontius Pilatus: La Nouvelle Clio 9, ’50, 495–514; EBammell, Syrian Coinage and Pilate: JJS 2, ’51, 108–10.—Pauly-W. XX, 1322s.; Kl. Pauly IV 1049; BHHW III 1472s. M-M. s.v. <span class=\"greek\">Πειλ</span>. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίμπλημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πίμπλημι</span>, futuro <span class=\"greek\">πλήσω</span> LXX; 1.º aoristo <span class=\"greek\">ἔπλησα</span>; particípio perfeito médio <span class=\"greek\">πεπλησμένα</span> (Just.). Passivo: 1.º futuro <span class=\"greek\">πλησθήσομαι</span>; 1.º aoristo <span class=\"greek\">ἐπλήσθην</span>, particípio <span class=\"greek\">πλησθείς</span> (Hom. e outros; papiros, LXX, En; TestSol 6:5 D; TestJob 27:3; JosAs; SibOr 3, 311; Joseph.; Just., D. 73, 6.—Sobre a grafia, B-D-F §93; 101; Thackeray p. 110; Mlt-H. 106. Transitivo no presente e imperfeito, ao passo que o correspondente <span class=\"greek\">πλήθω</span> é intransitivo nesses tempos).<br>① Fazer ficar completamente cheio, encher, completar.<br>ⓐ Literalmente.<br><span class=\"greek\">α</span>. Acerca de coisas externas e perceptíveis, <span class=\"greek\">τὶ</span> «alguma coisa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:7</a>; <span class=\"greek\">τί</span> <span class=\"greek\">τινος</span> «encher alguma coisa de outra coisa» (Hom. e outros; PLond II, 453, 6 p. 319 [IV d.C.]; LXX): uma esponja com vinagre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:48</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:36</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:29</a>, variante textual. Passivo (Jos., Ant. 3, 299): <span class=\"greek\">ἐπλήσθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">γάμος</span> [variante textual <span class=\"greek\">νυμφών</span>] <span class=\"greek\">ἀνακειμένων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:10</a>. <span class=\"greek\">ἐπλήσθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πόλις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">συγχύσεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:29</a>.—<span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκία</span> <span class=\"greek\">ἐπλήσθη</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀσμῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:3</a>, variante textual (Hom. Hymns, Dem. 280 <span class=\"greek\">αὐγῆς</span> <span class=\"greek\">ἐπλήσθη</span> <span class=\"greek\">δόμος</span>).<br><span class=\"greek\">β</span>. Acerca da vida interior de uma pessoa (Hom. e outros; Diod S 15, 37, 2 <span class=\"greek\">φρονήματος</span> [de entusiasmo] <span class=\"greek\">ἐπίμπλαντο</span>; PGM 13, 234 <span class=\"greek\">πλησθεὶς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θεοσοφίας</span>; LXX), passivo: <span class=\"greek\">ἐπλήσθησαν</span> <span class=\"greek\">φόβου</span> (Appian, Bell. Civ. 4, 48 §204) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:26</a>; <span class=\"greek\">ἀνοίας</span> 6:11; <span class=\"greek\">θάμβους</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐκστάσεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:10</a>; <span class=\"greek\">ζήλου</span> 5:17; 13:45; <span class=\"greek\">θυμοῦ</span> (Da 3:19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:28</a>; <span class=\"greek\">χαρᾶς</span> AcPl Ha 2, 15; 8, 7. Acerca do Espírito Santo (cf. Sir 48:12a; Pr 15:4.—Dio Chrys. 55 [72], 12, a Pítia é <span class=\"greek\">ἐμπιμπλαμένη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span>): <span class=\"greek\">πνεύματος</span> <span class=\"greek\">ἁγίου</span> <span class=\"greek\">πλησθήσεται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:15</a>; cf. vv. 41, 67; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:4</a>; 4:8, 31; 9:17; 13:9; AcPl Ha 6, 17. <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> Hm 11, 9 (com Ox 5 recto, 5; variante textual <span class=\"greek\">πληρωθείς</span>).<br>ⓑ Figuradamente.<br><span class=\"greek\">α</span>. Acerca de profecias, passivo «cumprir-se» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:20</a>, variante textual; 21:22.<br><span class=\"greek\">β</span>. Acerca de período de tempo que transcorre ou chega ao fim, passivo: <span class=\"greek\">ἐπλήσθησαν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἡμέραι</span> «os dias chegaram ao fim» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:23</a>. Acrescenta-se um genitivo que indica o acontecimento que sucede quando o tempo se esgota: <span class=\"greek\">ἐπλήσθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">χρόνος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τεκεῖν</span> <span class=\"greek\">αὐτήν</span> «chegou o tempo de ela dar à luz» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.57\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:57</a> (cf. Hdt. 6, 63, 1; 69, 5, acerca da gestação). Cf. 2:6, 21, 22.<br><span class=\"greek\">γ</span>. <span class=\"greek\">ἐπλήσθησαν</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἀνομίαι</span> <span class=\"greek\">αὐτῶν</span> «a medida de suas iniquidades ficou completa» Hv 2, 2, 2.<br>② Satisfazer completamente uma necessidade, saciar; passivo, «ser saciado, ficar satisfeito», <span class=\"greek\">τινός</span> «de alguma coisa» (Soph., Ant. 121; epigrama de Ptolemaeus: Anth. Pal. 9, 577 <span class=\"greek\">πίμπλαμαι</span> <span class=\"greek\">ἀμβροσίης</span>), <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀσεβείας</span> 1 Cl 57:6 (Pr 1:31).—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίμπρημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πίμπρημι</span>, passivo: <span class=\"greek\">πίμπραμαι</span>, infinitivo <span class=\"greek\">πίμπρασθαι</span>; particípio do 1.º aoristo <span class=\"greek\">πρησθείς</span> (Hom. e outros; inscrições, LXX; Tat. 24, 1.—Sobre a grafia, veja B-D-F §93; 101; Mlt-H. 106; Thackeray p. 110). Termo médico (Hobart 50), mas de modo algum restrito à profissão médica; contudo, raro na prosa grega mais antiga, que prefere o composto <span class=\"greek\">ἐμπίμπρημι</span>. O passivo significa ou ① arder de febre (Pherecrates Com. [V a.C.], Fgm. 80, 4 Kock; SIG 1179, 15 [veja nota 6]; 1180, 3) ou ② ficar distendido, inchar (Hippocr. e outros; SIG 1169, 123; Num 5:21, 27; Jos., Ant. 3, 271. Field, Notes 149). Acerca de Judas, Papias (3:2). Ambos os significados são possíveis em <span class=\"greek\">προσεδόκων</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">μέλλειν</span> <span class=\"greek\">πίμπρασθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:6</a>.—B. 75. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πινακίδιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πινακίδιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (veja a entrada seguinte; Hippocr., Aristot. e outros), diminutivo de <span class=\"greek\">πίναξ</span>, pequena tabuinha (de madeira), especialmente tabuinha de escrita para anotações (Epict. 3, 22, 74; Ezk 9:2 Sym.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.63\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:63</a>.—DELG s.v. <span class=\"greek\">πίναξ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0286-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πινακίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πινακίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span>, pequena tabuinha (de madeira) para escrever (veja a entrada anterior; Macho [III a.C.] em Athen. 13, 582c e outros; WSchubart, Der Gnomon d. Idios Logos 1919 [=BGU V] 36; PRyl 144, 19 [38 d.C.]; Sym. Ezk 9:11; Artapanus em Eus., PE 9, 27, 26), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.63\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:63</a>, variante textual.—DELG s.v. <span class=\"greek\">πίναξ</span>. M-M s.v. <span class=\"greek\">πινακίδιον</span>.</p></section></article>"};
